    corazones: { n: 'Corazones', e: '💖', a: 'sube', como: 'Grita ¡YUPI! 25 veces', ok: p => p.st.yupi >= 25 },
    fuego: { n: 'Fuego imparable', e: '🔥', a: 'sube', como: 'Gana 5 partidas seguidas', ok: p => p.st.mejor >= 5 },
    nieve: { n: 'Nieve navideña', e: '❄️', a: 'cae', como: 'Juega durante el Evento de Navidad', ok: p => !!eventoActivo() || !!p.ev?.navidad },
    confeti: { n: 'Confeti', e: '🎊', a: 'cae', como: 'Llega al nivel 10', ok: p => nivelDe(p.xp).n >= 10 },
    totora: { n: 'Lago Titicaca', e: '🐟', a: 'orbita', como: 'Vence al Cóndor Kuntur', ok: p => !!p.av[20] },
